<script lang="ts">
import { useTranslate } from '@tolgee/vue';
import { storeToRefs } from 'pinia';
import { useRoute } from 'vue-router';
import { ref, defineComponent } from 'vue';
import { usePoAndInvoiceStore } from '../store';
import { useSettingStore, useAmountFormatStore } from 'src/store/main';
import SubHeader from 'src/pages/Settings/Components/Sub-Header.vue';
import { getStatusColor } from 'src/pages/PurchaseOrders/constants.js';
import SupplierItemNumberMap from 'src/components/SupplierItemNumberMap.vue';
import BackToSettings from 'src/pages/Settings/Components/BackToSettings.vue';
import { purchaseOrderService } from 'src/services';
import type { dynamicObj } from 'src/pages/assets';
import axios from 'axios';
import { isEmptyString, isUndefinedOrNull } from 'src/utils/general';
import { ApiExceptions } from 'src/exceptions';
import { DOC2API_URL } from 'src/pages/APIs';
import { useImageAuth } from 'src/composables/useImageAuth';
import dateUtils from 'src/utils/date';
import { notify } from 'src/components/notifications/notify';

export default defineComponent({
  mixins: [dateUtils],
  props: {},
  data() {
    return {
      showSupplierMapDlg: ref(false),
      formattedAmount: ref(''),
      skeletonLoad: ref(false),
      iframe_path: ref(''),
      pdfObjectUrl: '' as string,
    };
  },
  components: { SubHeader, BackToSettings, SupplierItemNumberMap },
  mounted() {
    this.init();
  },
  beforeUnmount() {
    if (this.pdfObjectUrl) {
      URL.revokeObjectURL(this.pdfObjectUrl);
      this.pdfObjectUrl = '';
    }
  },
  methods: {
    init() {
      this.getDataServer();
    },
    async getDataServer() {
      try {
        this.preview_path = '';
        this.loading = true;
        this.skeletonLoad = true;
        const values: string[] = [];
        await this.getPurchaseOrderDetail(this.id);
        const response = await purchaseOrderService.getPoCharges({
          purchase_order_numbers:
            this.po_detail.purchase_order.purchase_order_number,
        });
        if (response.success) {
          const poCharges = response.data;
          this.po_detail.purchase_order_line.map((po: dynamicObj) => {
            po.charges = poCharges.filter(
              (charge: dynamicObj) => charge.line_number === po.line_number,
            );
            for (const charge of po.charges) {
              values.push(charge.amount);
              // charge.formattedAmount = await this.formatAmount(charge.amount);
            }
            po.show_charges = false;
            return po;
          });
          this.columns.unshift();
        }
        const formatResults = await this.formatAmount(values);
        const poCharges = response.data;
        this.po_detail.purchase_order_line.map((po: dynamicObj) => {
          po.charges = poCharges.filter(
            (charge: dynamicObj) =>
              charge.line_number === po.line_number &&
              charge.sub_line_number === po.sub_line_number,
          );
          for (const charge of po.charges) {
            charge.formattedAmount = this.searchValueByKey(
              charge.amount,
              formatResults,
            );
          }
          po.show_charges = false;
          return po;
        });
        await this.getPreviewPathDetails();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
        this.skeletonLoad = false;
      }
    },

    async getPreviewPathDetails() {
      try {
        if (
          !isUndefinedOrNull(this.preview_path) &&
          !isEmptyString(this.preview_path)
        ) {
          this.getPdfFileDetails();
          return;
        }

        try {
          this.skeletonLoad = true;
          await this.getPreviewPath(this.id);
          await this.getPdfFileDetails();
        } catch (err: any) {
          logError(err);
        } finally {
          this.skeletonLoad = false;
        }
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err);
        const errorFrame = document.getElementById(
          'preview_frame',
        ) as HTMLIFrameElement;
        const errorDoc = errorFrame.contentDocument;
        if (errorDoc) {
          errorDoc.write('<h1>Error</h1><p>Oops!  ' + msg + '.</p>');
          errorDoc.close();
        }
        logError(err);
      }
    },
    async getPdfFileDetails() {
      try {
        if (
          isUndefinedOrNull(this.preview_path) ||
          isEmptyString(this.preview_path)
        ) {
          return;
        }

        await this.refreshTokenParam();

        try {
          this.skeletonLoad = true;
          const response = await axios.get(
            `${DOC2API_URL}/resource/get_file/${this.po_number_path}?path=${this.preview_path}&download=false&${this.tokenQueryParam}`,
            {
              responseType: 'blob',
            },
          );

          if (response.headers['content-type'] == 'application/json') {
            notify.warning(this.$t('pdf_preview_not_available'));
            logError(new Error('PDF preview not available for this PO'));
            return;
          }

          if (this.pdfObjectUrl) {
            URL.revokeObjectURL(this.pdfObjectUrl);
          }
          this.pdfObjectUrl = URL.createObjectURL(response.data);
          this.iframe_path = this.pdfObjectUrl;
        } catch (e) {
          logError(e);
        } finally {
          this.skeletonLoad = false;
        }
      } catch (err: any) {
        logError(err);
      }
    },

    statusColor(status: string) {
      return getStatusColor(status.toLowerCase()) || 'primary';
    },
    getTextRightAligement(field: string) {
      return field === 'total_amount' ||
        field === 'unit_price' ||
        field === 'quantity' ||
        field === 'line_number' ||
        field === 'received_quantity' ||
        field === 'geo_code'
        ? 'text-right'
        : 'text-left';
    },
    searchValueByKey(key: string, values: dynamicObj[]) {
      return useAmountFormatStore().searchValueByKey(key, values);
    },
    async formatAmount(amount: string | string[]) {
      let values: Array<{ key: string | number; value: string | number }> = [];
      if (Array.isArray(amount)) {
        values = amount.map((a) => {
          return {
            key: a,
            value: a,
          };
        });
      } else if (amount) {
        values.push({
          key: amount,
          value: amount,
        });
      } else {
        values.push({
          key: 0,
          value: 0,
        });
      }
      const { user_settings } = useSettingStore();
      const result = await useAmountFormatStore().formatMultiValues(
        values,
        'en_US',
        user_settings.AMOUNTS_LOCALE,
      );
      return result;
    },
  },
  setup() {
    const { t } = useTranslate();
    const dashboard_purchase_order_store = usePoAndInvoiceStore();
    const route = useRoute();
    const id = ref<any>(route.params.purchase_number);
    const columns = ref<any[]>([
      { field: '', label: '' },
      { field: 'status', label: t.value('status') },
      { field: 'line_number', label: t.value('line_number') },
      { field: 'item_id', label: t.value('item_id') },
      { field: 'supplier_item_id', label: t.value('supplier_item_id') },
      { field: 'description', label: t.value('description') },
      { field: 'quantity', label: t.value('quantity') },
      { field: 'received_quantity', label: t.value('received_quantity') },
      { field: 'unit_price', label: t.value('po_unit_price') },
      { field: 'total_amount', label: t.value('total_amount') },
    ]);
    const { datePattern, statusInterface, dateFormatOnly } = useSettingStore();
    const {
      display_data,
      loading,
      table_columns,
      po_detail,
      preview_path,
      po_number_path,
    } = storeToRefs(dashboard_purchase_order_store);
    const { getPurchaseOrderData, getPurchaseOrderDetail, getPreviewPath } =
      dashboard_purchase_order_store;
    const { tokenQueryParam, refreshTokenParam } = useImageAuth();

    return {
      getPurchaseOrderData,
      getPurchaseOrderDetail,
      dashboard_purchase_order_store,
      id,
      loading,
      display_data,
      po_detail,
      table_columns,
      columns,
      datePattern,
      statusInterface,
      dateFormatOnly,
      purchaseOrderService,
      preview_path,
      getPreviewPath,
      po_number_path,
      tokenQueryParam,
      refreshTokenParam,
    };
  },
});
</script>

